@startuml

class User {
  + userID : int
  + name : string
  + email : string
  + dateOfBirth : date
}

class Account {
  + accountNumber : int
}

class PersonalAccount {
}

class BusinessAccount {
  + companyName : string
  + monthlyFee : double
}

class Page {
  + pageName : string
  + visitCount : int
}

class AdvertisementPage {
  + bounceRate : float
  + clickThroughRate : float
  + conversionRate : float
}

class FriendRequest {
}

User "1" -- "1" Account
Account --|> PersonalAccount
Account --|> BusinessAccount
PersonalAccount --|> Account
BusinessAccount --|> Account

Account "1" -- "*" Page : creates
PersonalAccount "1" -- "*" FriendRequest : sends
PersonalAccount "1" -- "*" FriendRequest : receives
PersonalAccount "0..*" -- "*" Page : has privileges

Page --|> AdvertisementPage
BusinessAccount "1" -- "*" AdvertisementPage : creates

